import { skipToken } from '@reduxjs/toolkit/query/react';
import { useEffect, useMemo, useState } from 'react';
import { Controller, useForm } from 'react-hook-form';
import { useNavigate } from 'react-router-dom-v5-compat';

import { AppEvents } from '@grafana/data';
import { t } from '@grafana/i18n';
import { getAppEvents, isFetchError, reportInteraction } from '@grafana/runtime';
import {
  Alert,
  Button,
  Checkbox,
  Combobox,
  ControlledCollapse,
  Field,
  Input,
  RadioButtonGroup,
  SecretInput,
  Stack,
  Switch,
} from '@grafana/ui';
import {
  type Repository,
  useGetFrontendSettingsQuery,
  useGetRepositoryRefsQuery,
} from 'app/api/clients/provisioning/v0alpha1';
import { FormPrompt } from 'app/core/components/FormPrompt/FormPrompt';

import { DeleteRepositoryButton } from '../Repository/DeleteRepositoryButton';
import { TokenPermissionsInfo } from '../Shared/TokenPermissionsInfo';
import { getGitProviderFields, getLocalProviderFields } from '../Wizard/fields';
import { PROVISIONING_URL } from '../constants';
import { useConnectionList } from '../hooks/useConnectionList';
import { useConnectionOptions } from '../hooks/useConnectionOptions';
import { useCreateOrUpdateRepository } from '../hooks/useCreateOrUpdateRepository';
import { type RepositoryFormData } from '../types';
import { connectionTypesForProvider } from '../utils/connectionData';
import { dataToSpec, deriveSigningKeySecret } from '../utils/data';
import { extractFormErrors, getConfigFormErrors } from '../utils/getFormErrors';
import { getHasTokenInstructions, getRemoteConfig } from '../utils/git';
import { getRepositoryTypeConfig, isGitProvider, supportsWebhooks } from '../utils/repositoryTypes';

import { BranchOptionsSection } from './BranchOptionsSection';
import { CommitOptionsSection } from './CommitOptionsSection';
import { EnablePushToConfiguredBranchOption } from './EnablePushToConfiguredBranchOption';
import { PullRequestOptionsSection } from './PullRequestOptionsSection';
import { WebhookSection } from './WebhookSection';
import { getDefaultValues } from './defaults';

// This needs to be a function for translations to work
const getTargetOptions = (allowedTargets: string[]) => {
  const allOptions = [
    { value: 'instance', label: t('provisioning.config-form.option-entire-instance', 'Entire instance') },
    { value: 'folder', label: t('provisioning.config-form.option-managed-folder', 'Managed folder') },
    { value: 'folderless', label: t('provisioning.config-form.option-folderless', 'Folderless') },
  ];

  return allOptions.filter((option) => allowedTargets.includes(option.value));
};

export interface ConfigFormProps {
  data?: Repository;
}
export function ConfigForm({ data }: ConfigFormProps) {
  const repositoryName = data?.metadata?.name;
  const settings = useGetFrontendSettingsQuery();
  const [submitData, request] = useCreateOrUpdateRepository(repositoryName);
  const navigate = useNavigate();
  const {
    register,
    handleSubmit,
    reset,
    control,
    formState: { errors, isDirty },
    setValue,
    setError,
    watch,
    getValues,
  } = useForm<RepositoryFormData>({
    defaultValues: getDefaultValues({
      repository: data?.spec,
      allowedTargets: settings.data?.allowedTargets,
    }),
  });

  const isEdit = Boolean(repositoryName);
  const [tokenConfigured, setTokenConfigured] = useState(isEdit);
  const [isLoading, setIsLoading] = useState(false);
  const [submitError, setSubmitError] = useState<string | undefined>();
  const [type, readOnly, watchedConnectionName] = watch(['type', 'readOnly', 'connectionName']);
  const targetOptions = useMemo(() => getTargetOptions(settings.data?.allowedTargets || ['folder']), [settings.data]);
  const isGitBased = isGitProvider(type);

  // Repositories that authenticate through a provisioning connection (GitHub App
  // or OAuth app) have a connection reference in their spec; PAT-based
  // repositories store credentials directly.
  const connectionName = data?.spec?.connection?.name;
  const usesConnection = Boolean(connectionName && isGitProvider(type));

  // Offer connections of the same type as the referenced one, mirroring the
  // wizard where the kind (app vs OAuth) is fixed before picking a connection.
  // Reuses the same RTK Query cache entry as useConnectionOptions.
  const [allConnections, allConnectionsLoading, allConnectionsError] = useConnectionList(
    usesConnection ? {} : skipToken
  );
  const referencedConnectionType = allConnections?.find((c) => c.metadata?.name === connectionName)?.spec?.type;
  // The referenced connection may have been deleted; fall back to every connection kind
  // for this provider so a replacement can be picked.
  const connectionTypes = referencedConnectionType
    ? [referencedConnectionType]
    : isGitProvider(type)
      ? connectionTypesForProvider(type)
      : [];

  const {
    options: connectionOptions,
    isLoading: connectionsLoading,
    connections,
  } = useConnectionOptions(usesConnection, connectionTypes);

  const selectedConnection = connections.find((c) => c.metadata?.name === watchedConnectionName);
  const connectionWebhookDisabled = Boolean(selectedConnection?.spec?.webhook?.disabled);
  const emailWebhookDisabled = type === 'bitbucket' && !usesConnection && !watch('email')?.trim();

  useEffect(() => {
    if (connectionWebhookDisabled) {
      setValue('webhook.disabled', true);
    }
  }, [connectionWebhookDisabled, setValue]);

  const {
    data: refsData,
    isLoading: refsLoading,
    error: refsError,
  } = useGetRepositoryRefsQuery(!repositoryName || !isGitBased ? skipToken : { name: repositoryName });

  const branchOptions = useMemo(() => {
    if (!refsData?.items) {
      return [];
    }

    return refsData.items.map((ref) => ({
      label: ref.name,
      value: ref.name,
    }));
  }, [refsData?.items]);

  // Get field configurations based on provider type
  const gitFields = isGitBased ? getGitProviderFields(type) : null;
  const localFields = type === 'local' ? getLocalProviderFields(type) : null;
  const hasTokenInstructions = getHasTokenInstructions(type);

  useEffect(() => {
    if (request.isSuccess) {
      const formData = getValues();

      reportInteraction('grafana_provisioning_repository_updated', {
        repositoryName: repositoryName ?? 'unknown',
        repositoryType: formData.type,
        target: formData.sync?.target ?? 'unknown',
      });

      reset(formData);
      setTimeout(() => navigate(PROVISIONING_URL), 300);
    }
  }, [request.isSuccess, reset, getValues, repositoryName, navigate]);

  const onSubmit = async (form: RepositoryFormData) => {
    setIsLoading(true);
    setSubmitError(undefined);
    try {
      const spec = dataToSpec(form);
      // A token copied from a connection is bound to the old connection/repository;
      // removing it satisfies the backend's new-token-on-URL-change rule and makes
      // the controller mint a fresh token from the (possibly new) connection.
      const originalConnectionName = data?.spec?.connection?.name;
      const originalUrl = getRemoteConfig(data?.spec)?.url;
      const connectionChanged = Boolean(
        originalConnectionName && form.connectionName && form.connectionName !== originalConnectionName
      );
      const urlChanged = Boolean(usesConnection && originalUrl && form.url !== originalUrl);
      await submitData(spec, {
        token: connectionChanged || urlChanged ? { remove: true } : form.token ? { create: form.token } : undefined,
        commitSigningKey: deriveSigningKeySecret(form, Boolean(data?.secure?.commitSigningKey?.name)),
      });
    } catch (err) {
      if (isFetchError(err)) {
        const fieldErrors = getConfigFormErrors(err.data);

        if (fieldErrors.length > 0) {
          for (const [field, errorMessage] of fieldErrors) {
            setError(field, errorMessage);
          }
          return;
        }

        // Show unmapped error details as a top-level form error
        const allErrors = extractFormErrors(err.data);
        const detail = allErrors.find((e) => e.detail)?.detail;
        if (detail) {
          setSubmitError(detail);
          return;
        }
      }

      // fallback for non-fetch errors or errors without details
      defaultAlert();
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} style={{ maxWidth: 700 }}>
      <FormPrompt onDiscard={reset} confirmRedirect={isDirty} />
      <Stack direction="column" gap={2}>
        {submitError && (
          <Alert
            severity="error"
            title={t('provisioning.config-form.error-save-failed', 'Failed to save repository setting')}
          >
            {submitError}
          </Alert>
        )}
        <Field noMargin label={t('provisioning.config-form.label-repository-type', 'Repository type')}>
          <Input id="repository-type" value={getRepositoryTypeConfig(type)?.label || type} disabled />
        </Field>
        <Field
          noMargin
          label={t('provisioning.config-form.label-title', 'Title')}
          description={t('provisioning.config-form.description-title', 'A human-readable name for the config')}
          invalid={!!errors.title}
          error={errors?.title?.message}
        >
          <Input
            {...register('title', {
              required: t('provisioning.config-form.error-required', 'This field is required.'),
            })}
            placeholder={t('provisioning.config-form.placeholder-my-config', 'My config')}
          />
        </Field>
        {gitFields && (
          <>
            {usesConnection ? (
              <Field
                noMargin
                label={t('provisioning.config-form.label-connection', 'Connection')}
                description={t('provisioning.config-form.description-connection', 'Select the connection to use')}
                error={errors?.connectionName?.message}
                invalid={!!errors.connectionName}
              >
                <Controller
                  name="connectionName"
                  control={control}
                  rules={{
                    required: t('provisioning.config-form.error-connection-required', 'Connection is required'),
                    validate: (value) => {
                      // Membership is unknowable while the list loads (Save is disabled then) or
                      // after a load failure — fall back to server-side validation in those cases.
                      if (!value || allConnectionsLoading || allConnectionsError) {
                        return true;
                      }
                      return (
                        connections.some((c) => c.metadata?.name === value) ||
                        t(
                          'provisioning.config-form.error-connection-missing',
                          'This connection no longer exists. Select a replacement.'
                        )
                      );
                    },
                  }}
                  render={({ field: { ref, onChange, ...field } }) => (
                    <Combobox
                      options={connectionOptions}
                      onChange={(option) => onChange(option?.value ?? '')}
                      loading={connectionsLoading}
                      disabled={connectionsLoading}
                      invalid={!!errors.connectionName}
                      {...field}
                    />
                  )}
                />
              </Field>
            ) : (
              <Field
                noMargin
                label={gitFields.tokenConfig.label}
                required={gitFields.tokenConfig.required}
                error={errors?.token?.message}
                invalid={!!errors.token}
                description={gitFields.tokenConfig.description}
              >
                <Controller
                  name={'token'}
                  control={control}
                  rules={{
                    required: isEdit ? false : gitFields.tokenConfig.validation?.required,
                  }}
                  render={({ field: { ref, ...field } }) => {
                    return (
                      <SecretInput
                        {...field}
                        invalid={!!errors.token}
                        id={'token'}
                        placeholder={gitFields.tokenConfig.placeholder}
                        isConfigured={tokenConfigured}
                        revealable
                        onReset={() => {
                          setValue('token', '');
                          setTokenConfigured(false);
                        }}
                      />
                    );
                  }}
                />
              </Field>
            )}
            {gitFields.tokenUserConfig && (!usesConnection || type === 'git') && (
              <Field
                noMargin
                label={gitFields.tokenUserConfig.label}
                required={gitFields.tokenUserConfig.required}
                error={errors?.tokenUser?.message}
                invalid={!!errors?.tokenUser}
                description={gitFields.tokenUserConfig.description}
              >
                <Input
                  {...register('tokenUser', {
                    required: gitFields.tokenUserConfig.validation?.required,
                  })}
                  placeholder={gitFields.tokenUserConfig.placeholder}
                />
              </Field>
            )}
            {gitFields.emailConfig && !usesConnection && (
              <Field
                noMargin
                label={gitFields.emailConfig.label}
                required={gitFields.emailConfig.required}
                error={errors?.email?.message}
                invalid={!!errors?.email}
                description={gitFields.emailConfig.description}
              >
                <Input
                  {...register('email', {
                    required: gitFields.emailConfig.validation?.required,
                    pattern: gitFields.emailConfig.validation?.pattern,
                  })}
                  type="email"
                  placeholder={gitFields.emailConfig.placeholder}
                />
              </Field>
            )}
            {hasTokenInstructions && !usesConnection && <TokenPermissionsInfo type={type} url={watch('url')} />}
            <Field
              noMargin
              label={gitFields.urlConfig.label}
              error={errors?.url?.message}
              invalid={!!errors?.url}
              description={gitFields.urlConfig.description}
              required={gitFields.urlConfig.required}
            >
              <Input
                {...register('url', {
                  required: gitFields.urlConfig.validation?.required,
                  pattern: gitFields.urlConfig.validation?.pattern,
                  validate: gitFields.urlConfig.validation?.validate,
                })}
                placeholder={gitFields.urlConfig.placeholder}
              />
            </Field>
            <Field
              noMargin
              label={gitFields.branchConfig.label}
              description={gitFields.branchConfig.description}
              error={
                errors?.branch?.message ||
                (refsError ? t('provisioning.config-form.error-fetch-branches', 'Failed to fetch branches') : undefined)
              }
              invalid={Boolean(errors?.branch?.message || refsError)}
            >
              <Controller
                name="branch"
                control={control}
                rules={gitFields.branchConfig.validation}
                render={({ field: { ref, onChange, ...field } }) => (
                  <Combobox
                    invalid={Boolean(errors?.branch?.message || refsError)}
                    onChange={(option) => onChange(option?.value || '')}
                    placeholder={gitFields.branchConfig.placeholder}
                    options={branchOptions}
                    loading={refsLoading}
                    isClearable
                    {...field}
                  />
                )}
              />
            </Field>
            <Field noMargin label={gitFields.pathConfig.label} description={gitFields.pathConfig.description}>
              <Input id="repository-path" {...register('path')} />
            </Field>
          </>
        )}

        {localFields && (
          <Field
            noMargin
            label={localFields.pathConfig.label}
            error={errors?.path?.message}
            invalid={!!errors?.path}
            description={localFields.pathConfig.description}
            required={localFields.pathConfig.required}
          >
            <Input
              {...register('path', {
                required: localFields.pathConfig.validation?.required,
              })}
              placeholder={localFields.pathConfig.placeholder}
            />
          </Field>
        )}

        <Field noMargin>
          <Checkbox
            {...register('readOnly', {
              onChange: (e) => {
                if (e.target.checked) {
                  setValue('prWorkflow', false);
                  setValue('enablePushToConfiguredBranch', false);
                }
              },
            })}
            label={t('provisioning.finish-step.label-read-only', 'Read only')}
            description={t(
              'provisioning.config-form.description-read-only',
              "Resources can't be modified through Grafana."
            )}
          />
        </Field>

        {gitFields && (
          <Field noMargin>
            <Checkbox
              disabled={readOnly}
              {...register('prWorkflow')}
              label={gitFields.prWorkflowConfig.label}
              description={gitFields.prWorkflowConfig.description}
            />
          </Field>
        )}
        {isGitBased && (
          <EnablePushToConfiguredBranchOption<RepositoryFormData>
            register={register}
            registerName="enablePushToConfiguredBranch"
            readOnly={readOnly}
          />
        )}
        {isGitBased && (
          <>
            <BranchOptionsSection<RepositoryFormData>
              register={register}
              nameTemplateName="branchOptions.nameTemplate"
              enforceTemplateName="branchOptions.enforceTemplate"
            />
            <CommitOptionsSection<RepositoryFormData>
              register={register}
              control={control}
              setValue={setValue}
              messageTemplateName="commit.singleResourceMessageTemplate"
              enforceTemplateName="commit.enforceTemplate"
              type={type}
              signingMethodName="signingMethod"
              signingKeyName="commitSigningKey"
              smimeCertificateName="smimeCertificate"
              authorNameName="commit.authorName"
              authorEmailName="commit.authorEmail"
              signerNameName="commit.signerName"
              signerEmailName="commit.signerEmail"
              signerIsAuthorName="commit.signerIsAuthor"
              defaultSigningKeyConfigured={Boolean(data?.secure?.commitSigningKey?.name)}
            />
            {/* Pull requests are not supported by the pure git type. */}
            {type !== 'git' && (
              <PullRequestOptionsSection<RepositoryFormData>
                register={register}
                titleTemplateName="pullRequest.titleTemplate"
                enforceTemplateName="pullRequest.enforceTemplate"
                repoType={type}
                dashboardPreviewName="generateDashboardPreviews"
              />
            )}
          </>
        )}
        {supportsWebhooks(type) && (
          <WebhookSection<RepositoryFormData>
            register={register}
            control={control}
            name="webhook.baseUrl"
            disabledName="webhook.disabled"
            connectionWebhookDisabled={connectionWebhookDisabled}
            disabledReason={
              emailWebhookDisabled
                ? t(
                    'provisioning.webhook-section.description-webhook-disabled-email',
                    'Webhook integration is disabled because the Atlassian account email is not set. Set it above to enable webhooks.'
                  )
                : undefined
            }
            disabledError={errors?.webhook?.disabled?.message}
          />
        )}

        {isGitBased && (
          <ControlledCollapse
            label={t('provisioning.config-form.label-automatic-pulling', 'Automatic pulling')}
            isOpen={false}
          >
            <Stack direction="column" gap={2}>
              <Field
                noMargin
                label={t('provisioning.config-form.label-enabled', 'Enabled')}
                description={t(
                  'provisioning.config-form.description-enabled',
                  'Once automatic pulling is enabled, the target type below cannot be changed.'
                )}
              >
                <Switch {...register('sync.enabled')} id={'sync.enabled'} />
              </Field>
              <Field
                noMargin
                label={t('provisioning.config-form.label-target', 'Target')}
                required
                error={errors?.sync?.target?.message}
                invalid={!!errors?.sync?.target}
              >
                <Controller
                  name={'sync.target'}
                  control={control}
                  rules={{ required: t('provisioning.config-form.error-required', 'This field is required.') }}
                  render={({ field: { ref, onChange, ...field } }) => {
                    return (
                      <RadioButtonGroup
                        options={targetOptions}
                        onChange={onChange}
                        disabled={Boolean(data?.status?.sync.state)}
                        {...field}
                      />
                    );
                  }}
                />
              </Field>
              <Field
                noMargin
                label={t('provisioning.config-form.label-interval-seconds', 'Interval (seconds)')}
                error={errors?.sync?.intervalSeconds?.message}
                invalid={!!errors?.sync?.intervalSeconds}
              >
                <Input
                  {...register('sync.intervalSeconds', { valueAsNumber: true })}
                  type={'number'}
                  placeholder={t('provisioning.config-form.placeholder-interval-seconds', '60')}
                />
              </Field>
            </Stack>
          </ControlledCollapse>
        )}

        <Stack gap={2}>
          <Button type={'submit'} disabled={isLoading || (usesConnection && allConnectionsLoading)}>
            {isLoading
              ? t('provisioning.config-form.button-saving', 'Saving...')
              : t('provisioning.config-form.button-save', 'Save')}
          </Button>
          {repositoryName && data && (
            <DeleteRepositoryButton name={repositoryName} repository={data} redirectTo={PROVISIONING_URL} />
          )}
        </Stack>
      </Stack>
    </form>
  );
}

const defaultAlert = () => {
  getAppEvents().publish({
    type: AppEvents.alertError.name,
    payload: [t('provisioning.wizard-content.error-save-repository-setting', 'Failed to save repository setting')],
  });
};
